<template>
  <div class="profile-view text-light">
    <CompanyNavBar v-if="user.userRole === 0" />
    <NavBarVue v-else />

    <b-row>
      <b-col lg="2" md="4" sm="0"></b-col>
      <b-col>
        <b-overlay :show="isLoading" rounded="sm">
          <h4 class="text-light mt-2">
            <b-icon icon="person-fill"></b-icon>
            <b>{{ user.name }} - {{ convertRole(user.userRole) }}</b>
          </h4>
          <b-icon icon="envelope-fill"></b-icon> <b>E-mail: </b>
          <small>{{ user.email }}</small
          ><br />
          <b-icon icon="telephone-forward-fill"></b-icon> <b>Telemóvel: </b>
          <small>{{ user.phone }}</small
          ><br />
          <b-icon icon="calendar2-day-fill"></b-icon> <b>Data de cadastro: </b>
          <small v-date-format="user.createdAt"></small><br />

          <hr class="bg-primary mt-2 mb-1" style="" />
          <b v-if="updatedPassword == 0" class="text-danger"
            ><b-icon icon="exclamation-circle-fill"></b-icon> Altere a sua
            palavra passe para continuar a usar os nossos serviços.</b
          >
          <b v-else
            ><b-icon icon="exclamation-circle-fill"></b-icon> Alterar a palavra
            passe</b
          >

          <b-row>
            <b-col lg="4"
              ><b-form-group
                label="Digite a sua senha actual"
                class="mt-0"
                label-for="input-1"
              >
                <b-form-input
                  v-model="form.password"
                  size="sm"
                  type="password"
                  placeholder="Senha actual"
                  required
                ></b-form-input> </b-form-group
            ></b-col>
            <b-col lg="4"
              ><b-form-group
                label="Digite a nova senha"
                class="mt-0"
                label-for="input-1"
              >
                <b-form-input
                  v-model="form.newPassword"
                  size="sm"
                  type="password"
                  placeholder="Nova senha"
                  required
                ></b-form-input> </b-form-group
            ></b-col>
            <b-col lg="4"
              ><b-form-group
                label="Digite novamente a nova senha"
                class="mt-0"
                label-for="input-1"
              >
                <b-form-input
                  v-model="form.confirmPassword"
                  size="sm"
                  type="password"
                  placeholder="Digite novamente a nova senha"
                  required
                ></b-form-input> </b-form-group
            ></b-col>
          </b-row>
          <b-row>
            <b-col lg="8"></b-col>
            <b-col>
              <b-button
                :disabled="isLoading"
                type="submit"
                size="sm"
                block
                variant="secondary"
                @click="updatePassword()"
                >Actualizar &nbsp;<b-icon icon="telegram"></b-icon
              ></b-button>
            </b-col>
          </b-row>
        </b-overlay>
      </b-col>
      <b-col lg="2" md="4" sm="0"></b-col>
    </b-row>
  </div>
</template>

<script>
import { mapGetters } from "vuex";
import axios from "axios";

import NavBarVue from "@/components/NavBar";
import CompanyNavBar from "@/components/CompanyNavBar.vue";
import logs from "@/utils/logs";

export default {
  name: "ProfileView",

  data: () => ({
    form: {
      name: "",
      email: "",
      phone: "",
      password: "",
      newPassword: "",
      confirmPassword: "",
      companyId: "",
      userRole: "",
      status: "",
      createdAt: "",
      updatedAt: "",
    },
  }),

  components: {
    NavBarVue,
    CompanyNavBar,
  },

  created() {
    this.form = this.user;
    this.form.password = "";
    this.form.newPassword = "";
    this.form.confirmPassword = "";
  },

  computed: {
    ...mapGetters(["isLoading", "user", "token", "updatedPassword"]),
  },

  methods: {
    updatePassword() {
      if (
        this.form.password.length < 4 ||
        this.form.newPassword.length < 6 ||
        this.form.confirmPassword < 6
      ) {
        this.showToast(
          "Aviso!",
          "warning",
          "As senhas devem conter no mínimo 6 caracteres."
        );
        return;
      } else {
        if (this.form.newPassword != this.form.confirmPassword) {
          this.showToast("Aviso!", "warning", "As senhas não coincidem.");
        } else {
          const passingValues = {
            password: this.form.password,
            newPassword: this.form.newPassword,
            email: this.form.email,
            updatedPassword: 1,
          };
          this.$store.commit("LOADING_STATUS", true);
          axios
            .post(`/api/updatePassword`, passingValues)
            .then((res) => {
              const data = res.data;
              if (data.success == true) {
                this.showToast("Sucesso!", "success", data.message);
                this.logoutUser();
              } else {
                this.showToast("Erro!", "danger", data.message);
              }
              this.$store.commit("LOADING_STATUS", false);
              this.resetForm();
            })
            .catch((err) => {
              this.showToast("Erro!", "danger", err.message);
              this.$store.commit("LOADING_STATUS", false);
              this.resetForm();
            });
        }
      }
    },

    resetForm() {
      this.form = this.user;
      this.form.password = "";
      this.form.newPassword = "";
      this.form.confirmPassword = "";
    },

    showToast(title, variant, msg) {
      this.$bvToast.toast(`${msg}`, {
        title,
        variant,
        solid: true,
        toaster: "b-toaster-top-center",
        autoHideDelay: 5000,
      });
    },

    convertRole(role) {
      if (role == -1) {
        return "Front Office";
      } else if (role == 0) {
        return "Súper Admin";
      } else if (role == 1) {
        return "Admin";
      } else if (role == 2) {
        return "Atendimento";
      } else if (role == 3) {
        return "Avalista";
      }
    },

    convertStatus(status) {
      if (status === 1) {
        return "Activo";
      } else if (status === 0) {
        return "Bloaqueado";
      }
    },

    logoutUser() {
      const logsParams = logs(
        this.user,
        `${this.user.email} - ${this.user.name} Actualização da senha.`,
        "Autenticação"
      );
      this.$store.dispatch("addLog", logsParams).then(() => {
        this.$store.dispatch("actionDoLogout");
        this.$router.push("/");
      });
    },
  },
};
</script>
