<template>
  <div>
    <b-navbar
      class="navbar"
      toggleable="lg"
      type="dark"
      variant="secondary"
      fixed="true"
    >
      <b-navbar-brand to="/">
        <img
          :src="company.companyLogo"
          alt="Company LOGO"
          style="border-radius: 50%"
          width="40"
        />
        &nbsp;&nbsp;<span v-if="company">{{ company.companyName }}</span>
      </b-navbar-brand>

      <b-navbar-toggle target="nav-collapse"></b-navbar-toggle>

      <b-collapse id="nav-collapse" is-nav>
        <b-navbar-nav style="font-size: 10pt">
          <b-nav-item to="/reports"
            ><b-icon icon="pie-chart-fill"></b-icon> RELATÓRIOS</b-nav-item
          >
        </b-navbar-nav>

        <!-- Right aligned nav items -->
        <b-navbar-nav class="ml-auto">
          <!-- <b-nav-form>
            <b-form-input
              size="sm"
              class="mr-sm-2"
              placeholder="Pesquisar clientes"
            ></b-form-input>
            <b-button size="sm" class="my-2 my-sm-0" type="submit"
              >Pesquisar</b-button
            >
          </b-nav-form> -->

          <!-- <b-nav-item-dropdown :text="language" right>
            <b-dropdown-item>PT</b-dropdown-item>
            <b-dropdown-item>EN</b-dropdown-item>
          </b-nav-item-dropdown> -->

          <b-nav-item-dropdown right>
            <!-- Using 'button-content' slot -->
            <template #button-content>
              <small class="text-light">Olá {{ user.name }}</small>
              <b-icon
                icon="person-fill"
                variant="light"
                font-scale="1.5"
              ></b-icon>
            </template>
            <b-dropdown-item to="/profile">Perfil</b-dropdown-item>
            <b-dropdown-item to="/system_logs"
              >Histórico de operações</b-dropdown-item
            >
            <b-dropdown-item @click="logoutUser()">Sair</b-dropdown-item>
          </b-nav-item-dropdown>
        </b-navbar-nav>
      </b-collapse>
    </b-navbar>
  </div>
</template>

<script>
import axios from "axios";
import { mapGetters } from "vuex";
import logs from "@/utils/logs";

export default {
  data: () => ({
    language: "PT",
  }),

  computed: {
    ...mapGetters(["user", "token", "company"]),
  },

  created() {
    if (this.token) {
      axios.defaults.headers.common["Authorization"] = `Bearer ${this.token}`;
      this.getCompany();
    }
  },

  methods: {
    logoutUser() {
      const logsParams = logs(
        this.user,
        `${this.user.email} - ${this.user.name} terminou a sessão.`,
        "Autenticação"
      );
      this.$store.dispatch("addLog", logsParams).then(() => {
        this.$store.dispatch("actionDoLogout");
        this.$router.push("/");
      });
    },

    getCompany() {
      this.$store
        .dispatch("getCompanyDetails", this.user.companyId)
        .then((/*res*/) => {})
        .catch((err) => {
          console.log(err.message);
          this.logoutUser();
        });
    },
  },
};
</script>
<style scoped>
.nav-item {
  display: flex;
  align-content: center;
  align-items: flex-start;
}
</style>
